import * as React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Slot } from './slot';
import { describe, it, expect } from 'vitest';

const Input = React.forwardRef<
  React.ComponentRef<'input'>,
  React.ComponentProps<'input'> & { asChild?: boolean }
>(({ asChild, children, ...props }, forwardedRef) => {
  const Comp = asChild ? Slot : 'input';
  const [value, setValue] = React.useState('');

  return (
    <Comp
      {...props}
      onChange={(event) => setValue(event.target.value)}
      ref={forwardedRef}
      value={value}
    >
      {children}
    </Comp>
  );
});

describe('repro maximum update depth', () => {
  it('types into an asChild Input without infinite loop', async () => {
    const handleRef = vi.fn();
    render(
      <Input asChild ref={handleRef}>
        <input />
      </Input>,
    );
    await userEvent.type(screen.getByRole('textbox'), 'foo');
    expect(screen.getByRole('textbox')).toHaveValue('foo');
  });
});

